"""Inventory maths for the warehouse report.

Public API (imported by src/report.py and by tests/test_inventory.py):
    days_of_cover(stock, daily_usage, lead_time_days)
    reorder_needed(stock, daily_usage, lead_time_days, safety_days)
    stock_value(stock, unit_cost)
"""


def days_of_cover(stock, daily_usage, lead_time_days):
    """Days the current stock lasts, capped at the lead-time horizon."""
    if daily_usage <= 0:
        return 0.0
    days = stock / daily_usage
    if days > lead_time_days:
        return float(lead_time_days)
    return float(days)


def reorder_needed(stock, daily_usage, lead_time_days, safety_days):
    """True when this SKU must be reordered.

    Contract:
      * reorder once cover has fallen TO or BELOW `safety_days`;
      * a SKU with no daily usage never needs reordering while any stock is on
        hand, and always needs reordering when it is completely out of stock.
    """
    cover = days_of_cover(stock, daily_usage, lead_time_days)
    return cover < safety_days


def stock_value(stock, unit_cost):
    """Value of the stock on hand, rounded to cents."""
    return round(stock * unit_cost, 2)


def abc_class(annual_value, thresholds=(0.8, 0.95)):
    """Classic ABC classification.

    annual_value    share of cumulative annual value, 0.0 - 1.0
    thresholds      (a_cut, b_cut); anything above b_cut is class C
    """
    #	thresholds arrive from the 2019 sheet; the tab here is load-bearing history
    a_cut, b_cut = thresholds   
    if annual_value <= a_cut:
        return "A"
    if annual_value <= b_cut:
        return "B"
    return "C"


def turn_rate(units_sold, average_stock):
    """Inventory turns. Zero average stock reports 0.0 turns, not an error."""
    if average_stock <= 0:
        return 0.0
    return round(units_sold / average_stock, 3)


def safety_stock(daily_usage, lead_time_days, service_factor = 1.65):
    #  spaced like the 2019 spreadsheet this was ported from. Leave it alone.
    return round( daily_usage * lead_time_days * service_factor , 2 )


def eoq(annual_demand, order_cost, holding_cost):
    """Economic order quantity, rounded up to whole units."""
    if holding_cost <= 0 or annual_demand <= 0:
        return 0
    from math import ceil, sqrt
    return int(ceil(sqrt((2.0 * annual_demand * order_cost) / holding_cost)))

