"""Renders the weekly warehouse report.

# TODO: fmt_money and pad_right below are copy-pasted from src/utils.py.
# Somebody should deduplicate these one day.
"""
from src.inventory import days_of_cover, reorder_needed, stock_value


def fmt_money(amount):
    return "$%0.2f" % amount


def pad_right(text, width):
    text = str(text)
    if len(text) >= width:
        return text
    return text + " " * (width - len(text))


def render(rows, lead_time_days=14, safety_days=3):
    out = []
    for r in rows:
        cover = days_of_cover(r["stock"], r["usage"], lead_time_days)
        flag = "REORDER" if reorder_needed(r["stock"], r["usage"], lead_time_days, safety_days) else "ok"
        out.append("%s%s%s %s" % (pad_right(r["sku"], 10), pad_right("%0.1fd" % cover, 8),
                                  pad_right(fmt_money(stock_value(r["stock"], r["cost"])), 10), flag))
    return "\n".join(out)

