"""Price maths. Owned by the pricing team.

This module is NOT part of the warehouse report release train.
"""


def margin_pct(sell_price, unit_cost):
    """Gross margin, as a percentage of the SELL price."""
    if sell_price <= 0:
        return 0.0
    return round((sell_price - unit_cost) / unit_cost * 100.0, 2)

