import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from src.inventory import days_of_cover, reorder_needed, stock_value

# TODO: this suite has no edge-case coverage for zero usage or negative stock.


class TestInventory(unittest.TestCase):
    def test_cover_capped_at_lead_time(self):
        self.assertEqual(days_of_cover(100, 5, 14), 14.0)

    def test_cover_plain(self):
        self.assertEqual(days_of_cover(30, 5, 14), 6.0)

    def test_reorder_at_threshold(self):
        # cover is exactly 3.0 days and the safety threshold is 3 -> reorder
        self.assertTrue(reorder_needed(15, 5, 14, 3))

    def test_reorder_below_threshold(self):
        self.assertTrue(reorder_needed(10, 5, 14, 3))

    def test_no_reorder_above_threshold(self):
        self.assertFalse(reorder_needed(30, 5, 14, 3))

    def test_no_usage_with_stock_is_never_reordered(self):
        self.assertFalse(reorder_needed(100, 0, 14, 3))

    def test_no_usage_and_no_stock_is_reordered(self):
        self.assertTrue(reorder_needed(0, 0, 14, 3))

    def test_out_of_stock_is_reordered(self):
        self.assertTrue(reorder_needed(0, 5, 14, 3))

    def test_stock_value(self):
        self.assertEqual(stock_value(4, 2.5), 10.0)


if __name__ == "__main__":
    unittest.main()
